mapper.select:
SELECT action_log_id,admin_no,admin_login_id,admin_name,action,target_type,target_id,request_id,target_label,
  before_status,after_status,reason,created_at,is_sample AS sample
FROM ultary_admin_action_log  ORDER BY created_at DESC,action_log_id DESC LIMIT #{limit} OFFSET #{offset}

choose.when:
SELECT r.status AS after_status,CONCAT('#',t.hashtag) AS target_label FROM ultary_tag_profile_request r
JOIN ultary_tag t ON t.tag_id=r.tag_id WHERE r.tag_id=#{id}
AND r.tag_profile_request_id=#{requestId}
ORDER BY r.tag_profile_request_id DESC LIMIT 1

mapper.insert:
INSERT INTO ultary_admin_action_log(admin_no,admin_login_id,admin_name,action,target_type,target_id,request_id,target_label,before_status,after_status,reason)
SELECT a.admin_no,a.login_id,a.name,#{action},#{targetType},#{targetId},#{requestId},#{targetLabel},#{beforeStatus},#{afterStatus},#{reason}
FROM ultary_admin a WHERE a.admin_no=#{adminNo}

mapper.select:
SELECT (
  SELECT COUNT(*) FROM ultary_pet p
  WHERE p.user_no=#{userNo} AND p.profile_file_id=#{fileId}
) + (
  SELECT COUNT(*) FROM ultary_story s
  WHERE s.user_no=#{userNo} AND (s.file_id=#{fileId} OR s.thumbnail_file_id=#{fileId})
) + (
  SELECT COUNT(*) FROM ultary_feed f
  JOIN ultary_feed_media m ON m.feed_id=f.feed_id
  WHERE f.user_no=#{userNo} AND (m.file_id=#{fileId} OR m.thumbnail_file_id=#{fileId})
)
